// Sends a page view event to the analytics service.
// In a real app this would POST to your analytics provider.
export async function logPageView({
  path,
  userAgent,
}: {
  path: string
  userAgent: string
}) {
  await fetch('https://analytics.example.com/collect', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ event: 'page_view', path, userAgent, ts: Date.now() }),
  })
}

