import { after } from 'next/server'
import { headers } from 'next/headers'
import { logPageView } from './utils'

export default async function Home() {
  // Read request data BEFORE `after`. In Server Components, request-time APIs
  // like `headers()` cannot be called inside the `after` callback — read them
  // during render and pass the values in via closure.
  const userAgent = (await headers()).get('user-agent') || 'unknown'

  // Schedule the analytics log to run after the response is sent, so it
  // never blocks the user from receiving the page.
  after(() => {
    logPageView({ path: '/', userAgent })
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for stopping by — your visit was recorded in the background.</p>
    </main>
  )
}

